examples.setupTemplate:
var items by remember {
    mutableStateOf(
        listOf(
            MonarchLineItem({{items.0.id}}, {{items.0.description}}, BigDecimal("{{items.0.quantity|raw}}"), BigDecimal("{{items.0.unitPrice|raw}}")),
            MonarchLineItem({{items.1.id}}, {{items.1.description}}, BigDecimal("{{items.1.quantity|raw}}"), BigDecimal("{{items.1.unitPrice|raw}}")),
            MonarchLineItem({{items.2.id}}, {{items.2.description}}, BigDecimal("{{items.2.quantity|raw}}"), BigDecimal("{{items.2.unitPrice|raw}}")),
        ),
    )
}
var taxRate by remember { mutableStateOf(BigDecimal("{{taxRate|raw}}")) }
var discount by remember { mutableStateOf(MonarchLineItemsDiscount(MonarchLineItemsDiscountKind.{{discount.type|pascal}}, BigDecimal("{{discount.value|raw}}"))) }

